#!/bin/sh
# Runs apps/api/scripts/backup.ts with the superuser, inside the backup container:
# the service's own loop uses it, and so does a backup by hand.
#
#   docker exec <instance>_backup_prod sh /app/docker/backup.sh              a dump now
#   docker exec <instance>_backup_prod sh /app/docker/backup.sh --list
#   docker exec <instance>_backup_prod sh /app/docker/backup.sh --base --force
#
# The URL is built here, not in the container's config: the password (from .env,
# or generated by docker/generate-secrets.sh) never shows in `docker inspect`, so
# a plain `docker exec ... bun run scripts/backup.ts` has no DATABASE_URL.
set -eu
: "${POSTGRES_PASSWORD:=$(cat "${KITSUDEN_SECRETS_DIR:-/kitsuden-secrets}/postgres_password" 2>/dev/null || true)}"
if [ -z "$POSTGRES_PASSWORD" ]; then
  echo "backup: no POSTGRES_PASSWORD and no postgres_password in the secrets volume" >&2
  exit 1
fi
DATABASE_URL="postgresql://${KITSUDEN_DB_USER}:${POSTGRES_PASSWORD}@${KITSUDEN_DB_AT}"
export DATABASE_URL
unset POSTGRES_PASSWORD
cd /app/apps/api
exec bun run scripts/backup.ts "$@"
